import {BANK_VERSION,GROUPS,DOMAINS,freshState,scoreFacets,taskSummary,qualitySummary,buildChecks,snapshot,validateImport} from './core.js';
const $=s=>document.querySelector(s),KEY='atlas-discovery-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let facets=[],tasks=[],challenges=[],method={},checks=[],state=freshState(),view='survey',page=0,taskPage=0,challengePage=0,resultGroup='all',storageOk=true;
const labels=['전혀 그렇지 않다','그렇지 않다','약간 그렇지 않다','중간이다','약간 그렇다','그렇다','매우 그렇다'];
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500);}
function save(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));storageOk=true;}catch{storageOk=false;}$('#save-status').textContent=storageOk?'이 브라우저에 자동 저장됨':'저장 불가 · 답변을 내보내세요';updateCounts();}
function updateCounts(){const ids=new Set(facets.flatMap(f=>f.items.map(i=>i.id)));const n=Object.keys(state.answers).filter(id=>ids.has(id)).length;$('#survey-count').textContent=`${n} / 400`;$('#performance-count').textContent=`${Object.keys(state.taskAnswers).length} / 36`;if($('#submit-tasks'))$('#submit-tasks').disabled=state.taskSubmitted||!Object.keys(state.taskAnswers).length;$('#frontier-count').textContent=`${Object.values(state.challenges).filter(c=>c.text?.trim()).length} / 8`;}
function show(target,scroll=true){view=target;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});render();if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function progress(n,total,label){return `<div class="progress-row"><span>${esc(label)}</span><span>${n} / ${total}</span></div><div class="track" role="progressbar" aria-label="${esc(label)}" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${total}"><div class="fill" style="width:${total?n/total*100:0}%"></div></div>`;}
function render(){if(view==='survey')survey();else if(view==='performance')performance();else if(view==='frontier')frontier();else if(view==='evidence')evidence();else if(view==='results')results();else methodology();}
function survey(){const isCheck=page===facets.length;const f=isCheck?{label:'응답 점검',group:'checks',description:'처음 문항과 같은 문장이 일부 나옵니다. 기억하려 하지 말고 지금 판단으로 답하세요. 표시 확인 문항은 안내한 숫자를 선택하세요.',items:checks}:facets[page];const n=Object.keys(state.answers).filter(id=>facets.some(f=>f.items.some(i=>i.id===id))).length;$('#main').innerHTML=`<div class="eyebrow">01 / SELF OBSERVATION</div><h1>나를 관찰하는 400개의 질문</h1><p class="intro">최근 6개월의 평소 행동을 떠올리세요. 이상적인 모습보다 실제 모습을 답합니다. 경험이 없으면 ‘판단할 경험 없음’을 선택하세요.</p>${progress(n,400,'자기보고 진행')}<div class="note"><strong>연구용 자기탐색 초안</strong> · 이 검사에는 아직 표준화 자료가 없습니다. 재능 문항은 능력의 자기관찰이며 실제 실력을 확정하지 않습니다. 답변은 이 브라우저에만 저장됩니다. 공용 기기에서는 마친 뒤 초기화하세요.</div><div class="toolbar"><label for="section">문항 묶음<select id="section">${facets.map((f,i)=>`<option value="${i}" ${page===i?'selected':''}>${String(i+1).padStart(2,'0')} · ${esc(GROUPS[f.group])} / ${esc(f.label)}</option>`).join('')}<option value="${facets.length}" ${isCheck?'selected':''}>51 · 응답 점검 12문항</option></select></label><button id="next-unanswered" class="quiet">미응답 묶음으로 이동</button></div><div class="section-head"><div><h2>${esc(f.label)}</h2><p>${esc(f.description)}</p></div><span class="counter">${page+1} / 51 묶음</span></div><div class="items">${f.items.map((item,i)=>itemHTML(item,isCheck?'점검 '+(i+1):String(page*8+i+1).padStart(3,'0'))).join('')}</div><div class="pagination"><button id="prev" class="secondary" ${page===0?'disabled':''}>이전 묶음</button><span>1 = 전혀 아님 · 7 = 매우 그러함</span><button id="next" class="button">${page===facets.length?'결과 보기':'다음 묶음'}</button></div><footer>400문항 + 반복·표시 점검 12문항. 예상 80~120분이며 10~15분씩 나눠 풀어도 됩니다. 실제 소요 시간은 사람마다 다릅니다.</footer>`;
$('#section').onchange=e=>{page=+e.target.value;render();};$('#prev').onclick=()=>{page--;render();window.scrollTo(0,0);};$('#next').onclick=()=>{if(page===facets.length)show('results');else{page++;render();window.scrollTo(0,0);}};$('#next-unanswered').onclick=()=>{const p=facets.findIndex(f=>f.items.some(i=>state.answers[i.id]===undefined));page=p<0?facets.length:p;render();};$('#main').querySelectorAll('input[data-answer]').forEach(r=>r.onchange=()=>{state.answers[r.dataset.answer]=+r.value;save();});}
function itemHTML(item,num){const val=state.answers[item.id];return `<fieldset class="item"><legend><small>${esc(num)}</small>${esc(item.text)}</legend><div class="answers">${labels.map((l,j)=>`<label class="answer"><input type="radio" name="${esc(item.id)}" data-answer="${esc(item.id)}" value="${j+1}" ${val===j+1?'checked':''} aria-label="${j+1}. ${l}"><span aria-hidden="true">${j+1}</span></label>`).join('')}</div><div class="scale-ends"><span>전혀 그렇지 않다</span><span>매우 그렇다</span></div><label class="unknown"><input type="radio" name="${esc(item.id)}" data-answer="${esc(item.id)}" value="0" ${val===0?'checked':''}> 판단할 경험 없음 / 모르겠다</label></fieldset>`;}
function performance(){const t=tasks[taskPage],n=Object.keys(state.taskAnswers).length,locked=state.taskSubmitted;$('#main').innerHTML=`<div class="eyebrow">02 / PERFORMANCE</div><h1>생각을 실제로 사용해 보기</h1><p class="intro">검색·계산기·AI의 도움 없이 풀면 본인의 현재 수행을 관찰할 수 있습니다. 답을 고른 뒤 맞을 가능성을 예상하세요. 제출하면 정답이 공개되고 이 회차의 답변이 잠깁니다.</p>${progress(n,tasks.length,'수행 응답')}<div class="note warning">이 36문항은 새로 만든 과제입니다. IQ·영재성 판정에 사용할 수 없습니다. 언어, 학습 경험, 피로가 결과에 영향을 줍니다. 시간 제한은 없으며 처리 속도는 채점하지 않습니다.</div><div class="toolbar"><label for="task-select">과제 이동<select id="task-select">${tasks.map((q,i)=>`<option value="${i}" ${i===taskPage?'selected':''}>${i+1} · ${esc(DOMAINS[q.domain])} ${state.taskAnswers[q.id]!==undefined?'✓':''}</option>`).join('')}</select></label><span class="tag">${locked?'제출 완료 · 정답 검토':'아직 정답이 공개되지 않음'}</span></div><div class="task-box"><div class="section-head"><h2>${esc(t.title)}</h2><span class="counter">${taskPage+1} / 36</span></div><p class="task-prompt">${esc(t.prompt)}</p><fieldset style="border:0;padding:0;margin:0"><legend class="small muted">답 하나를 선택하세요.</legend><div class="choices">${t.options.map((o,i)=>`<label class="choice"><input type="radio" name="task" value="${i}" ${state.taskAnswers[t.id]===i?'checked':''} ${locked?'disabled':''}><span>${String.fromCharCode(65+i)}. ${esc(o)}</span></label>`).join('')}</div></fieldset><div class="confidence"><label for="confidence">이 답이 맞을 가능성</label><select id="confidence" ${locked?'disabled':''}><option value="">확신도 선택</option>${[0,10,25,40,50,60,75,90,100].map(v=>`<option value="${v}" ${state.taskConfidence[t.id]===v?'selected':''}>${v}%</option>`).join('')}</select><span class="small muted">확신도 미입력 과제는 확률 점수에서 제외됩니다.</span></div>${locked?`<div class="review-explanation"><strong>${state.taskAnswers[t.id]===undefined?'미응답':state.taskAnswers[t.id]===t.correct?'정답':'오답'} · 정답 ${String.fromCharCode(65+t.correct)}</strong><p>${esc(t.explanation)}</p></div>`:''}</div><div class="pagination"><button id="task-prev" class="secondary" ${taskPage===0?'disabled':''}>이전 과제</button><button id="task-next" class="secondary" ${taskPage===tasks.length-1?'disabled':''}>다음 과제</button></div><div class="toolbar"><button id="submit-tasks" class="button" ${locked||!n?'disabled':''}>수행 답변 제출</button><button id="view-task-results" class="quiet">결과 보기</button></div><footer>동일한 문항을 다시 풀면 연습 효과가 발생합니다. 재검사 때 수행 점수의 상승을 능력 향상으로 바로 해석하지 마세요.</footer>`;
$('#task-select').onchange=e=>{taskPage=+e.target.value;render();};$('#task-prev').onclick=()=>{taskPage--;render();};$('#task-next').onclick=()=>{taskPage++;render();window.scrollTo(0,0);};$('#main').querySelectorAll('input[name=task]').forEach(r=>r.onchange=()=>{state.taskAnswers[t.id]=+r.value;save();});$('#confidence').onchange=e=>{if(e.target.value==='')delete state.taskConfidence[t.id];else state.taskConfidence[t.id]=+e.target.value;save();};$('#submit-tasks').onclick=()=>confirmAction('수행 답변을 제출할까요?',`${n}개 과제를 답했습니다. 미응답 ${tasks.length-n}개는 채점에서 제외됩니다. 제출하면 정답이 공개되므로 이 회차의 답변을 바꿀 수 없습니다.`,()=>{state.taskSubmitted=true;save();show('results');},'제출하고 정답 공개');$('#view-task-results').onclick=()=>show('results');}
function frontier(){const c=challenges[challengePage],r=state.challenges[c.id]||{text:'',ratings:{}};$('#main').innerHTML=`<div class="eyebrow">03 / FRONTIER LAB</div><h1>정답이 없는 문제와 마주하기</h1><p class="intro">‘어려운 아이디어를 생각할 수 있다’에서 한 걸음 더 나아가, 무엇을 검증해야 할지 구체적으로 써보세요. 이 작업은 스스로 평가합니다. AI가 창의성이나 천재성을 채점하지 않습니다.</p><div class="toolbar"><label for="challenge-select">도전 과제<select id="challenge-select">${challenges.map((c,i)=>`<option value="${i}" ${challengePage===i?'selected':''}>${i+1}. ${esc(c.title)}</option>`).join('')}</select></label></div><div class="task-box"><h2>${esc(c.title)}</h2><p class="task-prompt">${esc(c.prompt)}</p><h3>설계 조건</h3><ul class="checklist">${c.constraints.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><label class="evidence-field" for="challenge-text">나의 해결안<span class="small">문제 정의 → 가정 → 대안 → 실패 가능성 → 최소 실험 → 관측할 결과 순서로 적어보세요. 실제로 수행한 부분과 계획을 구분합니다.</span><textarea id="challenge-text" maxlength="30000" placeholder="아이디어보다 검증할 수 있는 주장을 먼저 적어보세요.">${esc(r.text)}</textarea></label><h3>현재 답변에 대한 자기평가</h3><p class="small muted">0 증거 없음 · 1 주장만 있음 · 2 이유를 설명함 · 3 재현 가능한 검증 계획 · 4 실제 실행 결과를 기록함. 이 숫자는 외부 심사 점수가 아닙니다.</p><div class="rubric">${c.rubric.map((rr,i)=>`<label><div>${esc(rr.label)}<p>${esc(rr.description.split(" 각 항목은")[0])}</p></div><select data-rubric="${i}" aria-label="${esc(rr.label)} 자기평가"><option value="">미평가</option>${[0,1,2,3,4].map(v=>`<option ${r.ratings?.[i]===v?'selected':''} value="${v}">${v} 단계</option>`).join('')}</select></label>`).join('')}</div><div class="note"><strong>다음 실험</strong><br>${esc(c.experiment)}</div></div><div class="pagination"><button id="challenge-prev" class="secondary" ${challengePage===0?'disabled':''}>이전 과제</button><button id="challenge-next" class="button">${challengePage===challenges.length-1?'결과 보기':'다음 과제'}</button></div>`;
$('#challenge-select').onchange=e=>{challengePage=+e.target.value;render();};const ensure=()=>state.challenges[c.id]??={text:'',ratings:{}};$('#challenge-text').oninput=e=>{ensure().text=e.target.value;save();};$('#main').querySelectorAll('[data-rubric]').forEach(e=>e.onchange=()=>{const rr=ensure();if(e.value==='')delete rr.ratings[e.dataset.rubric];else rr.ratings[e.dataset.rubric]=+e.value;save();});$('#challenge-prev').onclick=()=>{challengePage--;render();};$('#challenge-next').onclick=()=>{if(challengePage===challenges.length-1)show('results');else{challengePage++;render();window.scrollTo(0,0);}};}
const evidenceLabels={spatial:['공간·설계','공간 관계, 도면, 형태를 다룬 작업'],quantitative:['수량·분석','수치 추정, 모델, 계산으로 판단한 작업'],verbal:['언어·설명','글, 설명, 토론으로 이해를 바꾼 작업'],systems:['시스템·구현','코드, 공정, 도구, 규칙을 실제로 만든 작업'],creative:['창의·발견','새 문제를 발견하거나 기존 방식과 다른 해결을 시험한 작업'],social:['협력·영향','다른 사람과의 조율이나 설득으로 결과를 만든 작업']};
function evidence(){const ctx=state.context;$('#main').innerHTML=`<div class="eyebrow">04 / BEHAVIORAL EVIDENCE</div><h1>점수 밖에 있는 증거</h1><p class="intro">완성물, 다른 사람의 반응, 여러 상황에서 반복된 행동을 기록합니다. 기회와 환경이 충분했는지도 함께 적어야 낮은 점수를 성급하게 해석하지 않을 수 있습니다.</p><h2>이번 회차의 상황</h2><div class="grid">${[['sleep','최근 수면','평소와 비슷함','평소보다 부족함','평소보다 충분함'],['fatigue','지금 피로','낮음','보통','높음'],['distraction','집중 환경','방해가 거의 없음','간헐적 방해','방해가 많음'],['opportunity','최근 6개월의 활동 기회','충분함','분야별 차이가 큼','대체로 부족함']].map(([id,l,...opts])=>`<label>${l}<br><select data-context="${id}"><option value="">기록 안 함</option>${opts.map(o=>`<option ${ctx[id]===o?'selected':''}>${o}</option>`).join('')}</select></label>`).join('')}</div><div class="note">증거도 본인이 입력하는 기록입니다. 확인된 외부 평가로 자동 인정하지 않습니다. 사람 이름·연락처·민감한 정보는 적을 필요가 없습니다.</div>${Object.entries(evidenceLabels).map(([id,[label,hint]])=>`<label class="evidence-field">${label}<span class="small">${hint}. 상황 / 내가 한 행동 / 결과 / 확인할 자료 / 반례 / 기회와 제약을 적어보세요.</span><textarea data-evidence="${id}" maxlength="30000" placeholder="최근 사례 1~3개와 결과를 적어보세요.">${esc(state.evidence[id]||'')}</textarea></label>`).join('')}<label class="evidence-field">7일 행동 관찰<span class="small">날짜 / 선택한 활동 / 투입 시간 / 몰입 / 끝낸 결과 / 피드백 / 방해 요인. 최소 3일 이상 다른 상황을 기록하면 자기보고를 다시 검토할 재료가 됩니다.</span><textarea data-evidence="diary" maxlength="30000" placeholder="날짜별로 한 줄씩 기록하세요. 기록 자체를 자동 채점하지 않습니다.">${esc(state.evidence.diary||'')}</textarea></label><div class="callout"><h3>다른 사람의 관찰을 받고 싶다면</h3><p class="small muted">완성물 한 개와 평가 기준을 지인에게 보여주고, 강점·약점 각각의 실제 사례를 요청하세요. 평가자가 누구인지보다 무엇을 관찰했는지 기록합니다. 의견이 다르면 상황 차이를 먼저 비교합니다.</p></div>`;
$('#main').querySelectorAll('[data-context]').forEach(e=>e.onchange=()=>{state.context[e.dataset.context]=e.value;save();});$('#main').querySelectorAll('[data-evidence]').forEach(e=>e.oninput=()=>{state.evidence[e.dataset.evidence]=e.value;save();});}
function facetRow(f,s){const p=state.previous?.facets.find(x=>x.id===s.id),change=s.score!==null&&p?.score!==null&&p?.score!==undefined?s.score-p.score:null;return `<article class="result-row"><div class="result-top"><h3>${esc(f.label)}</h3><span class="facet-value">${s.score===null?'해석 보류':s.score+' / 100'}</span></div>${s.score!==null?`<div class="bar" role="img" aria-label="${esc(f.label)} 원점수 환산값 ${s.score} / 100"><span style="width:${s.score}%"></span></div>`:''}<div class="small muted">${s.n} / ${s.total} 유효 응답${s.unknown?' · 경험 없음 '+s.unknown+'개':''}${change!==null?' · 이전 회차 대비 '+(change>0?'+':'')+change+' (변화의 유의성 미확인)':''}</div><details><summary>해석과 검증 실험</summary><p>${esc(f.description)}</p>${s.score===null?`<p>최소 ${s.minimum}개의 유효 응답이 필요합니다. 미응답이나 경험 부족은 낮은 능력의 증거가 아닙니다.</p>`:`<p><strong>현재 응답의 위치:</strong> ${s.score>=67?esc(f.high):s.score<=33?esc(f.low):'응답 평균이 가운데 구간입니다. 대부분 중간값인지, 상황별로 양쪽 행동을 보였는지 문항별로 확인하세요.'}</p><p><strong>높은 방향:</strong> ${esc(f.high)}</p><p><strong>낮은 방향:</strong> ${esc(f.low)}</p>`}<p><strong>확인할 실험:</strong> ${esc(f.experiment)}</p><p class="small">이 설명은 응답 방향을 해석하는 가설입니다. 성격 유형이나 타고난 한계를 확정하지 않습니다.</p></details></article>`;}
function results(){const scores=scoreFacets(facets,state),valid=scores.filter(s=>s.score!==null),q=qualitySummary(state,checks),ts=taskSummary(tasks,state),selected=resultGroup==='all'?scores:scores.filter(s=>s.group===resultGroup),upper=[...valid].sort((a,b)=>b.score-a.score).slice(0,3),eN=Object.entries(state.evidence).filter(([id,t])=>id!=='diary'&&t?.trim()).length;$('#main').innerHTML=`<div class="eyebrow">05 / PERSONAL ATLAS</div><h1>나의 결과 지도</h1><div class="print-title">ATLAS · ${esc(new Date(state.updatedAt).toLocaleDateString('ko-KR'))}</div><p class="intro">자기보고, 현재 수행, 작성한 증거를 나란히 봅니다. 어느 하나도 ‘천재성’을 판정하는 점수로 합치지 않습니다.</p><div class="note warning"><strong>0~100은 백분위가 아닙니다.</strong> 1~7 응답을 역채점한 평균의 선형 환산값입니다. 67 이상·33 이하는 설명 방향을 고르는 임시 구간이며, 인구 규준이나 진단 경계가 아닙니다. 아직 이 검사의 신뢰도·타당도·정확도는 확인되지 않았습니다.</div><div class="grid"><div class="metric"><span class="small muted">해석 가능한 세부 특성</span><div class="metric-value">${valid.length} <span class="small muted">/ 50</span></div><p>각 축의 8문항 중 최소 6개 응답</p></div><div class="metric"><span class="small muted">실제 수행</span><div class="metric-value">${state.taskSubmitted?ts.correct+' / '+ts.n:'제출 전'}</div><p>${state.taskSubmitted?'응답한 문항만 분모 · 전체 36문항':'정답 공개 전에는 점수를 표시하지 않음'}</p></div></div><div class="toolbar"><button id="print-results" class="secondary">결과 인쇄 / PDF 저장</button><button id="download-report" class="quiet">해석 보고서 내보내기</button></div>${!valid.length?'<div class="note">아직 충분한 응답이 없습니다. 자기보고의 한 묶음부터 답하면 해당 축의 결과를 볼 수 있습니다.</div>':`<div class="callout"><h2>먼저 확인할 관찰 가설</h2><p class="small muted">충분히 답한 축 중 상대적으로 높은 3개입니다. 서로 다른 특성을 비교하는 순위는 편의를 위한 정렬이며, ‘가장 뛰어난 재능’ 순위가 아닙니다.</p>${upper.map(s=>`<p><strong>${esc(s.label)}</strong> · ${esc(facets.find(f=>f.id===s.id).experiment)}</p>`).join('')}</div>`}<h2 style="margin-top:28px">50개 세부 특성</h2><div class="tabs" aria-label="결과 영역">${[['all','전체'],...Object.entries(GROUPS)].map(([id,l])=>`<button data-result-group="${id}" class="${resultGroup===id?'active':''}" aria-pressed="${resultGroup===id}">${esc(l)}</button>`).join('')}</div>${selected.map(s=>facetRow(facets.find(f=>f.id===s.id),s)).join('')}<section class="callout"><h2>응답을 다시 살펴볼 단서</h2><div class="table-wrap"><table><tbody><tr><th>표시 확인</th><td>${q.attentionN} / 4 응답 · 안내 숫자와 다른 응답 ${q.attentionMismatch}개</td></tr><tr><th>반복 문항</th><td>${q.pairN} / 8 쌍 비교 · 평균 차이 ${q.meanPairDifference===null?'계산 전':q.meanPairDifference.toFixed(2)+' / 6'} · 3단계 이상 차이 ${q.largePairDifferences}쌍</td></tr><tr><th>가장 많이 선택한 숫자</th><td>${q.mostUsed===null?'계산 전':Math.round(q.mostUsed*100)+'%의 유효 자기보고 응답'}</td></tr></tbody></table></div><p class="small muted">불일치나 같은 숫자의 반복은 부주의·거짓말을 확정하지 않습니다. 피로, 상황 변화, 문항 이해 차이도 원인이 됩니다. 이것은 집단 신뢰도 계수나 개인의 신뢰성 점수가 아닙니다.</p></section>${performanceReport(ts)}${convergenceReport(scores,ts)}<section class="callout"><h2>난제 해결과 행동 증거</h2><p>난제 답변 ${Object.values(state.challenges).filter(c=>c.text?.trim()).length} / 8개 · 행동 사례 ${eN} / 6영역 · 관찰일지 ${state.evidence.diary?.trim()?'작성됨':'미작성'}</p><p class="small muted">작성 여부만 집계했습니다. 내용의 독창성, 진실성, 완성도는 자동 검증되지 않습니다. 자기평가 단계 역시 외부 평가와 구분합니다.</p>${challenges.map(c=>{const r=state.challenges[c.id];if(!r?.text?.trim())return '';return `<details class="result-row"><summary>${esc(c.title)} · 내가 쓴 해결안과 평가</summary><p style="white-space:pre-line">${esc(r.text)}</p>${c.rubric.map((rr,i)=>`<p>${esc(rr.label)}: ${r.ratings[i]??'미평가'}${r.ratings[i]!==undefined?' / 4 (자기평가)':''}</p>`).join('')}</details>`;}).join('')}${Object.entries(evidenceLabels).filter(([id])=>state.evidence[id]?.trim()).map(([id,[label]])=>`<details class="result-row"><summary>${esc(label)} · 작성한 행동 사례</summary><p style="white-space:pre-line">${esc(state.evidence[id])}</p></details>`).join('')}</section><section class="callout"><h2>다음 2주에 확인할 것</h2><ol class="checklist"><li>관심 있는 축 2개를 선택하고, 각각의 실험을 실제로 수행합니다.</li><li>완성물·오류·소요 시간·외부 피드백을 기록합니다. 성공 사례와 반례를 둘 다 남깁니다.</li><li>2~4주 뒤 비슷한 상황에서 새 회차의 자기보고를 답합니다. 차이를 자동으로 유의미한 변화라 판단하지 않습니다.</li><li>같은 수행 과제는 정답 기억의 영향을 받습니다. 별도의 미공개 동형 과제가 생기기 전에는 재수행을 훈련 기록으로 봅니다.</li></ol></section><footer>ATLAS ${BANK_VERSION} · ${esc(new Date(state.updatedAt).toLocaleString('ko-KR'))} · ${Object.entries(state.context).filter(([,v])=>v).map(([,v])=>esc(v)).join(' / ')||'검사 상황 미기록'}</footer>`;
$('#main').querySelectorAll('[data-result-group]').forEach(b=>b.onclick=()=>{resultGroup=b.dataset.resultGroup;results();});$('#print-results').onclick=()=>{resultGroup='all';results();$('#main').querySelectorAll('details').forEach(d=>d.open=true);window.print();};$('#download-report').onclick=downloadReport;}
function performanceReport(ts){if(!state.taskSubmitted)return '<section class="callout"><h2>수행 결과</h2><p class="small muted">수행 답변을 제출하면 영역별 정답 수와 확률 판단 결과가 여기에 나타납니다.</p></section>';return `<section class="callout"><h2>영역별 현재 수행</h2><div class="table-wrap"><table><thead><tr><th>과제 영역</th><th>정답 / 응답</th><th>응답 / 전체</th></tr></thead><tbody>${ts.domains.map(d=>`<tr><td>${esc(DOMAINS[d.id])}</td><td>${d.n?d.correct+' / '+d.n:'미응답'}</td><td>${d.n} / ${d.total}</td></tr>`).join('')}</tbody></table></div><p class="small muted">각 영역 6문항뿐이며 난이도도 표준화되지 않았습니다. 영역 간 차이를 능력 순위로 해석하지 않습니다. 미응답은 오답으로 처리하지 않습니다.</p><h3 style="margin-top:22px">정답 확률을 얼마나 잘 예상했나</h3><p>확신도와 응답이 모두 있는 ${ts.confidenceN}문항 ${ts.brier===null?'':`· 평균 예상 ${Math.round(ts.meanConfidence*100)}% · 같은 문항의 실제 정답률 ${Math.round(ts.calibrationAccuracy*100)}% · Brier 점수 ${ts.brier.toFixed(3)} / 1 · 예상−실제 ${((ts.meanConfidence-ts.calibrationAccuracy)*100).toFixed(1)}%p`}</p><p class="small muted">Brier = 평균[(맞을 확률 − 정답 여부)²]. 0에 가까울수록 이 문항들에서 확률 예측 오차가 작습니다. 점수에는 실력·문제 난도도 영향을 주므로 순수한 자기인식 능력 점수가 아닙니다. 확신도 없는 문항은 제외합니다. ${ts.confidenceN<10?'현재 표본이 특히 작아 안정적인 결론을 내리기 어렵습니다.':''}</p></section>`;}
function convergenceReport(scores,ts){const mapping=[['quantitative','quantitative'],['spatial','spatial'],['verbal','verbal'],['systems','causal']];return `<section class="callout"><h2>자기관찰과 실제 수행을 나란히 보기</h2><div class="table-wrap"><table><thead><tr><th>관련 분야</th><th>자기관찰 환산값</th><th>관련 과제 정답 / 응답</th></tr></thead><tbody>${mapping.map(([fid,did])=>{const s=scores.find(s=>s.id===fid),d=ts.domains.find(d=>d.id===did);return `<tr><td>${esc(s?.label||fid)}</td><td>${s?.score!==null&&s?.score!==undefined?s.score+' / 100':'해석 보류'}</td><td>${state.taskSubmitted&&d.n?d.correct+' / '+d.n:'수행 자료 부족'}</td></tr>`;}).join('')}</tbody></table></div><p class="small muted">두 열은 서로 다른 것을 측정합니다. 점수를 빼서 과대·과소평가를 판정하지 않습니다. 눈에 띄는 차이가 있다면 경험의 범위, 문항 난도, 최근 사례를 확인할 질문으로 사용하세요.</p></section>`;}
function methodology(){const list=(title,arr)=>`<section class="callout"><h2>${title}</h2><ol class="checklist">${(arr||[]).map(s=>`<li>${esc(typeof s==='string'?s.replace(/^\d+\.\s*/,''):s.description||JSON.stringify(s))}</li>`).join('')}</ol></section>`;$('#main').innerHTML=`<div class="eyebrow">06 / METHODS & LIMITS</div><h1>무엇을 알 수 있고, 아직 알 수 없나</h1><p class="intro">더 많은 문항은 관찰 범위를 넓힙니다. 정확도가 높다는 증거는 표본 연구에서 나옵니다. 현존하는 검사를 뛰어넘었다고 주장하려면 독립적인 비교 검증이 먼저 필요합니다.</p><div class="note"><strong>검사의 정체</strong> · 모든 문항은 이 도구를 위해 작성한 탐색용 문항입니다. 기존 공인 검사를 그대로 실시하는 것이 아니며, 검증된 검사의 신뢰도·타당도를 물려받지 않습니다.</div><h2>구성과 채점</h2><div class="table-wrap"><table><thead><tr><th>부분</th><th>구성</th><th>해석</th></tr></thead><tbody><tr><td>성격</td><td>30축 × 8 = 240문항</td><td>정서·사회성·개방성·협력·실행의 연속적 성향</td></tr><tr><td>재능과 사고</td><td>20축 × 8 = 160문항</td><td>행동에 대한 자기관찰. 능력 검사를 대신하지 않음</td></tr><tr><td>응답 점검</td><td>반복 8 + 표시 확인 4</td><td>검토할 단서. 유효성 합격/불합격 판정 없음</td></tr><tr><td>수행</td><td>6영역 × 6 = 36과제</td><td>이 문항에서의 현재 정확도와 확률 예측</td></tr><tr><td>난제 해결</td><td>8개 개방형 작업</td><td>해결안과 검증 계획, 실행 증거의 자기평가</td></tr><tr><td>행동 증거</td><td>6분야 사례 + 7일 기록</td><td>상황·기회·결과를 확인할 자료</td></tr></tbody></table></div><p class="small muted">각 자기보고 축은 6개 정방향과 2개 역방향 문항으로 구성합니다. 역문항은 8−응답으로 바꾼 뒤 평균을 구합니다. 환산값 = (평균−1)÷6×100, 반올림. 8개 중 6개 미만 유효 응답이면 숫자를 표시하지 않습니다. 경험 없음과 미응답은 평균에서 제외합니다. 6개와 67/33 기준은 편의를 위한 공개된 설계 규칙이며, 경험적으로 검증된 경계값이 아닙니다.</p>${list('설계 원칙',method.principles)}${list('해석의 한계',method.limitations)}${list('정확도를 검증하려면',method.validationPlan)}<section class="callout"><h2>참고한 연구와 공식 자료</h2><p class="small muted">아래 자료는 설계 원리를 뒷받침합니다. 이 도구 자체를 검증한 자료는 아닙니다.</p><ol class="source-list">${(method.sources||[]).map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>${esc(s.claim)}</li>`).join('')}</ol></section><section class="callout"><h2>내 답변과 저장</h2><p class="small muted">답변을 서버로 보내는 기능이나 분석 추적기는 없습니다. 이 브라우저의 로컬 저장소를 사용하므로 다른 기기에는 자동 동기화되지 않습니다. 브라우저 데이터 삭제, 사생활 보호 모드 종료 등으로 기록이 사라질 수 있습니다. 답변 내보내기로 별도 보관하세요. 새 회차 시작은 현재 원응답을 지우고 비교용 축 점수만 유지하므로 먼저 내보내기를 권합니다.</p><button id="clear-data" class="secondary">이 브라우저의 검사 기록 삭제</button></section>`;$('#clear-data').onclick=()=>confirmAction('검사 기록을 모두 삭제할까요?','이 브라우저에 저장된 답변과 이전 회차 비교 기록이 지워집니다. 내보낸 파일은 지워지지 않습니다.',()=>{try{localStorage.removeItem(KEY);}catch{}state=freshState();page=0;save();show('survey');},'모두 삭제');}
function confirmAction(title,text,action,button='확인'){const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(title)}</h2><p class="muted">${esc(text)}</p><div class="toolbar"><button class="secondary" data-cancel>취소</button><button class="button" data-confirm>${esc(button)}</button></div>`;document.body.append(d);d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-confirm]').onclick=()=>{d.close();action();};d.addEventListener('close',()=>d.remove());d.showModal();}
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function exportAnswers(){const data={...state,report:{facets:scoreFacets(facets,state).map(({entries,...s})=>s),performance:state.taskSubmitted?taskSummary(tasks,state):null,quality:qualitySummary(state,checks)}};download(JSON.stringify(data,null,2),`ATLAS-answers-${new Date().toISOString().slice(0,10)}.json`,'application/json');toast('답변 파일을 내보냈습니다.');}
function downloadReport(){const ss=scoreFacets(facets,state),ts=taskSummary(tasks,state);const content=['# ATLAS · 성격과 재능 탐색 보고서',`작성 시각: ${state.updatedAt}`,`검사 버전: ${BANK_VERSION}`,'','연구용 초안. 규준·신뢰도·타당도 미확인. 0~100은 인구 백분위나 IQ가 아닌 원응답의 환산값이다. 천재성 총점은 산출하지 않는다.','',...ss.flatMap(s=>{const f=facets.find(f=>f.id===s.id);return[`## ${f.label}`,`유효 응답 ${s.n}/8 · 환산값 ${s.score??'해석 보류'}`,f.description,`높은 방향: ${f.high}`,`낮은 방향: ${f.low}`,`확인 실험: ${f.experiment}`,''];}),'## 수행 결과',state.taskSubmitted?`정답 ${ts.correct}/${ts.n}응답 (전체36). 확신도 표본 ${ts.confidenceN}. Brier ${ts.brier??'없음'}`:'미제출',...ts.domains.map(d=>`${DOMAINS[d.id]}: ${state.taskSubmitted?d.correct+'/'+d.n:'미제출'} (전체'+d.total+')`),'','## 난제 답변',...challenges.flatMap(c=>{const r=state.challenges[c.id];return r?.text?[`### ${c.title}`,r.text,...c.rubric.map((rr,i)=>`${rr.label}: ${r.ratings[i]??'미평가'} (자기평가)`),'']:[];}),'## 행동 증거',...Object.entries(state.evidence).flatMap(([id,v])=>v?[`### ${evidenceLabels[id]?.[0]||'7일 관찰'}`,v,'']:[]),'## 해석 한계',...(method.limitations||[]),'## 참고 자료',...(method.sources||[]).map(s=>`${s.title}: ${s.url} — ${s.claim}`)].join('\n');download(content,`ATLAS-report-${new Date().toISOString().slice(0,10)}.md`,'text/markdown;charset=utf-8');toast('보고서를 내보냈습니다.');}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const add=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};add({name:'read_assessment_progress',title:'검사 진행 읽기',description:'현재 브라우저에서 진행한 검사 수와 해석 가능한 축 수를 읽습니다. 원응답은 반환하지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('빈 객체를 입력하세요.');return{selfReportAnswered:Object.keys(state.answers).length,interpretableFacets:scoreFacets(facets,state).filter(s=>s.score!==null).length,performanceAnswered:Object.keys(state.taskAnswers).length,performanceSubmitted:state.taskSubmitted};}});add({name:'open_assessment_section',title:'검사 영역 열기',description:'응답을 변경하지 않고 선택한 검사 화면을 엽니다.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['survey','performance','frontier','evidence','results','method']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).length!==1||!['survey','performance','frontier','evidence','results','method'].includes(input.section))throw new Error('유효한 영역을 선택하세요.');show(input.section);return{openedSection:view};}});}
async function boot(){try{const data=await Promise.all(['personality-bank.json','talent-bank.json','performance-bank.json','frontier-challenges.json','methodology.json'].map(async p=>{const r=await fetch(p);if(!r.ok)throw new Error('문항 자료를 읽지 못했습니다.');return r.json();}));facets=[...(data[0].facets||data[0]),...(data[1].facets||data[1])];tasks=data[2].tasks||data[2];challenges=data[3].challenges||data[3];method=data[4];checks=buildChecks(facets);if(facets.length!==50||tasks.length!==36||challenges.length!==8)throw new Error('문항 구성에 오류가 있습니다.');let stored;try{stored=localStorage.getItem(KEY);}catch{storageOk=false;}if(stored){try{state=validateImport(JSON.parse(stored),facets,tasks,challenges,checks);}catch{toast('저장 기록을 읽지 못했습니다. 내보낸 파일을 불러올 수 있습니다.');}}page=facets.findIndex(f=>f.items.some(i=>state.answers[i.id]===undefined));if(page<0)page=facets.length;updateCounts();render();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));$('#export').onclick=exportAnswers;$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5000000){toast('5MB 이하의 답변 파일만 불러올 수 있습니다.');return;}try{const incoming=validateImport(JSON.parse(await file.text()),facets,tasks,challenges,checks);confirmAction('답변 파일을 불러올까요?','이 브라우저의 현재 회차가 파일의 기록으로 바뀝니다. 먼저 현재 답변을 내보내면 보관할 수 있습니다.',()=>{state=incoming;save();page=0;show('results');},'불러오기');}catch(err){toast(err.message||'답변 파일을 읽지 못했습니다.');}e.target.value='';};$('#new-run').onclick=()=>confirmAction('새 회차를 시작할까요?','현재 원응답과 수행 답변을 초기화합니다. 자기보고 축 점수만 이전 회차 비교용으로 유지합니다. 현재 답변이 필요하면 먼저 내보내세요.',()=>{state=freshState(snapshot(facets,tasks,state));page=0;taskPage=0;challengePage=0;save();show('survey');},'새 회차 시작');registerTools();if(!storageOk)toast('브라우저 저장을 사용할 수 없습니다. 답변을 내보내 보관하세요.');window.addEventListener('beforeunload',()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}});}catch(err){$('#main').innerHTML=`<h1>문항을 불러오지 못했습니다</h1><p class="error">${esc(err.message)}</p><button class="button" id="retry">다시 시도</button>`;$('#retry').onclick=()=>location.reload();}}
boot();
